import axios from 'axios';

// 新建一個 api.js 文件來集中管理 API URL
// 使用 Strapi Cloud URL 作為基礎 API URL
export const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || 'https://eloquent-splendor-a265f51ba3.strapiapp.com';


// 設置請求攔截器
axios.interceptors.request.use(
  config => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  error => {
    return Promise.reject(error);
  }
);

const handleApiError = (error) => {
  if (error.response) {
    return {
      success: false,
      error: error.response.data.message || '請求失敗'
    };
  }
  return {
    success: false,
    error: error.message || '網絡錯誤'
  };
};

const api = {
  auth: {
    login: async (credentials) => {
      try {
        
        const response = await axios.post(
          `${API_BASE_URL}/api/auth/local`, 
          {
            identifier: credentials.username,
            password: credentials.password
          }
        );


        if (response.data.jwt) {
          localStorage.setItem('token', response.data.jwt);
          localStorage.setItem('user', JSON.stringify({
            ...response.data.user,
            jwt: response.data.jwt
          }));
          return {
            success: true,
            user: response.data.user
          };
        } else {
          return {
            success: false,
            error: '登入失敗：未收到授權令牌'
          };
        }
      } catch (error) {
        return {
          success: false,
          error: error.response?.data?.error?.message || '服務器錯誤'
        };
      }
    },
    
    logout: () => {
      localStorage.removeItem('token');
      localStorage.removeItem('user');
    },
    
    verifyToken: async () => {
      const token = localStorage.getItem('token');
      if (!token) return { success: false };
      
      try {
        const response = await axios.get(`${API_BASE_URL}/api/users/me`, {
          headers: {
            Authorization: `Bearer ${token}`
          }
        });
        return { success: true, user: response.data };
      } catch (error) {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        return { success: false };
      }
    }
  },

  projects: {
    list: async () => {
      try {
        const token = localStorage.getItem('token');
        
        const response = await axios.get(
          `${API_BASE_URL}/projects`,
          {
            headers: {
              'Authorization': `Bearer ${token}`
            }
          }
        );
        return response.data;
      } catch (error) {
        throw error;
      }
    },

    get: async (id) => {
      const token = localStorage.getItem('token');
      const response = await axios.get(`${API_BASE_URL}/projects/${id}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      return response.data;
    },
    
    create: async (projectData) => {
      try {
        const token = localStorage.getItem('token');
        
        // 檢查數據大小
        const dataSize = JSON.stringify(projectData).length;
        
        if (dataSize > 45 * 1024 * 1024) { // 45MB 警告
        }

        const response = await axios.post(
          `${API_BASE_URL}/projects`, 
          projectData,
          {
            headers: {
              'Authorization': `Bearer ${token}`,
              'Content-Type': 'application/json'
            },
            maxContentLength: 50 * 1024 * 1024,  // 50MB
            maxBodyLength: 50 * 1024 * 1024      // 50MB
          }
        );
        return response.data;
      } catch (error) {
        if (error.response?.status === 413) {
          throw new Error('請求數據太大，請減少數據大小或分批發送');
        }
        throw error;
      }
    },
    
    update: async (id, projectData) => {
      try {
        const response = await axios.put(`${API_BASE_URL}/projects/${id}`, projectData);
        return response.data;
      } catch (error) {
        throw error;
      }
    },
    
    delete: async (id) => {
      try {
        const response = await axios.delete(`${API_BASE_URL}/projects/${id}`);
        return response.data;
      } catch (error) {
        throw error;
      }
    },

    getAll: async () => {
      try {
        const response = await axios.get(`${API_BASE_URL}/projects`);
        return response.data;
      } catch (error) {
        throw error;
      }
    },

    resetDatabase: async () => {
      try {
        const response = await axios.delete('/api/projects/reset-all');
        return response.data;
      } catch (error) {
        throw error;
      }
    }
  }
};

export default api; 